INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_DISCORDIAN','Discordian Era (Principia Discordia to present)',1958,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_PRINCIPIA_DISCORDIA','primary text','Malaclypse the Younger (Greg Hill) & Omar Khayyam Ravenhurst (Kerry Thornley), Principia Discordia, or How I Found Goddess and What I Did to Her When I Found Her (1965; 4th ed. 1970)','Discordianism'),
 ('SRC_CUSACK_INVENTED_RELIGIONS','secondary scholarship','Carole M. Cusack, Invented Religions: Imagination, Fiction and Faith (Ashgate, 2010)','Discordianism')
INSERT INTO _e VALUES
 ('ENT_DIS_DISCORDIANISM','Discordianism','tradition_hub','Movement','Discordianism','chaos; absurdism; parody religion; individualism','B','Tradition-hub. Discordianism is an absurdist/parody religion founded 1958-63 by Greg Hill and Kerry Thornley and codified in the Principia Discordia; genuinely practiced worldwide (cabals, ordinations, the ''every man a Pope'' ethos) and influential on chaos magic. Attested in the Principia Discordia and treated as a sincerely-held invented religion in Cusack 2010.'),
 ('ENT_DIS_ERIS','Eris (Discordian Goddess of Chaos)','Goddess','Goddess','Discordianism','chaos; discord; creative disorder','B','The Discordian Eris/Discordia, central deity venerated by practicing Discordians as the benevolent Goddess of Chaos. An explicit modern reception of the ancient Greek Eris (ENT_ERIS); modeled neutrally as the sincerely-held object of Discordian devotion per the Principia Discordia. Homonym of, and reception_of, ENT_ERIS (Greek).'),
 ('ENT_DIS_SACRED_CHAO','The Sacred Chao','Sacred object','Symbol','Discordianism','cosmology; order and chaos; symbol','B','Core Discordian symbol (a yin-yang-like figure bearing the Apple of Discord and the Pentagon), used devotionally/ritually as the emblem of the interplay of order and disorder. Attested in the Principia Discordia.'),
 ('ENT_DIS_GOLDEN_APPLE','The Golden Apple of Discord (Discordian)','Sacred object','Relic','Discordianism','discord; chaos; relic','B','The golden apple inscribed ''kallisti'' (''to the prettiest one''), revered in Discordian practice as Eris''s defining relic and a sign of fruitful discord. A reception of the apple from the Greek Judgment of Paris myth, recontextualized in the Principia Discordia.'),
 ('ENT_DIS_GREYFACE','Greyface','Antagonist figure','Figure','Discordianism','order; seriousness; the curse of ''the Curse of Greyface''','C','The personified spirit of grim order and life-denying seriousness in Discordian myth; a man of c.1166 BC said to have taught that life is serious and play is wrong, originating ''the Curse of Greyface.'' The doctrinal antagonist of Eris/chaos; attested in the Principia Discordia.'),
 ('ENT_DIS_LAW_OF_FIVES','The Law of Fives','Doctrine','Doctrine','Discordianism','doctrine; numerology; hermeneutics','C','Core Discordian doctrine that all things happen in fives, or are divisible by or related to five (the ''Law of Fives is never wrong'' precisely because one can always find fives). Practiced as a half-serious interpretive/numerological lens; attested in the Principia Discordia.');
