INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_DIS_DISCORDIANISM','PER_DISCORDIAN','Tradition-hub. Discordianism is an absurdist/parody religion founded 1958-63 by Greg Hill and Kerry Thornley and codified in the Principia Discordia; genuinely practiced worldwide (cabals, ordinations, the ''every man a Pope'' ethos) and influential on chaos magic. Attested in the Principia Discordia and treated as a sincerely-held invented religion in Cusack 2010.'),
 ('ENT_DIS_ERIS','PER_DISCORDIAN','The Discordian Eris/Discordia, central deity venerated by practicing Discordians as the benevolent Goddess of Chaos. An explicit modern reception of the ancient Greek Eris (ENT_ERIS); modeled neutrally as the sincerely-held object of Discordian devotion per the Principia Discordia. Homonym of, and reception_of, ENT_ERIS (Greek).'),
 ('ENT_DIS_SACRED_CHAO','PER_DISCORDIAN','Core Discordian symbol (a yin-yang-like figure bearing the Apple of Discord and the Pentagon), used devotionally/ritually as the emblem of the interplay of order and disorder. Attested in the Principia Discordia.'),
 ('ENT_DIS_GOLDEN_APPLE','PER_DISCORDIAN','The golden apple inscribed ''kallisti'' (''to the prettiest one''), revered in Discordian practice as Eris''s defining relic and a sign of fruitful discord. A reception of the apple from the Greek Judgment of Paris myth, recontextualized in the Principia Discordia.'),
 ('ENT_DIS_GREYFACE','PER_DISCORDIAN','The personified spirit of grim order and life-denying seriousness in Discordian myth; a man of c.1166 BC said to have taught that life is serious and play is wrong, originating ''the Curse of Greyface.'' The doctrinal antagonist of Eris/chaos; attested in the Principia Discordia.'),
 ('ENT_DIS_LAW_OF_FIVES','PER_DISCORDIAN','Core Discordian doctrine that all things happen in fives, or are divisible by or related to five (the ''Law of Fives is never wrong'' precisely because one can always find fives). Practiced as a half-serious interpretive/numerological lens; attested in the Principia Discordia.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_DIS_ERIS','member_of','ENT_DIS_DISCORDIANISM','high','The Discordian Eris is the central deity of the Discordianism tradition-hub.'),
 ('ENT_DIS_SACRED_CHAO','member_of','ENT_DIS_DISCORDIANISM','high','The Sacred Chao is a core Discordian symbol belonging to the tradition.'),
 ('ENT_DIS_GOLDEN_APPLE','member_of','ENT_DIS_DISCORDIANISM','high','The Golden Apple is a foundational Discordian relic belonging to the tradition.'),
 ('ENT_DIS_GREYFACE','member_of','ENT_DIS_DISCORDIANISM','high','Greyface is a Discordian mythic figure belonging to the tradition.'),
 ('ENT_DIS_LAW_OF_FIVES','member_of','ENT_DIS_DISCORDIANISM','high','The Law of Fives is a core doctrine belonging to the Discordian tradition.'),
 ('ENT_DIS_ERIS','reception_of','ENT_ERIS','high','The Discordian Goddess of Chaos is an explicit modern reception/re-imagining of the ancient Greek Eris (ENT_ERIS), the founding act of Discordian invention per the Principia Discordia and Cusack 2010.'),
 ('ENT_DIS_ERIS','presides_over','ENT_DIS_SACRED_CHAO','medium','In Discordian cosmology Eris reveals/governs the Sacred Chao as the emblem of her ordered-and-chaotic cosmos.'),
 ('ENT_DIS_SACRED_CHAO','symbolizes','ENT_DIS_ERIS','high','The Sacred Chao is the central emblem of the Discordian Eris and her doctrine of the chaos/order interplay.'),
 ('ENT_DIS_GOLDEN_APPLE','symbolizes','ENT_DIS_ERIS','high','The kallisti-inscribed Golden Apple is Eris''s defining emblem in both the Greek myth and Discordian practice.'),
 ('ENT_DIS_GREYFACE','opposes','ENT_DIS_ERIS','high','Greyface, the spirit of grim order, is the doctrinal antagonist of the chaos-goddess Eris in Discordian myth.');
